def solve_costas_optimized(n):
    used_diffs = set()
    p = [0] * n
    used_rows = [False] * n

    def backtrack(col):
        if col == n:
            return True

        for row in range(n):
            if not used_rows[row]:
                # Check if all new displacement vectors are valid
                new_diffs = []
                possible = True
                for prev_col in range(col):
                    diff = (col - prev_col, row - p[prev_col])
                    if diff in used_diffs:
